package com.muxigame.city;

import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;

/** Authoritative maintenance settlements, followed by bounded, unloaded-safe world projection. */
public final class CityWorks {
 public static final class Plan {
  public Map<String,FoodAge.State> foodAges=new LinkedHashMap<>();
  public CityWorksLab.Run lab=new CityWorksLab.Run();
  public boolean virtual;public boolean finalized,enabled=true,emergency,emergencyAnnounced;public long clock,day,nextDecay=72000,nextSegment=3000,nextMeal=36000,revision,successions,migrantSilver,wages,materialCents,repaired,demolished,constructed,emergencyMeals;
  public int scan,privateCursor,cityPricePercent=100,wealthRatioPercent=100;
  public String status="尚未首次定稿";
  public Set<Long> terrainDamage=new LinkedHashSet<>();
  public Map<Long,Long> damageSince=new HashMap<>();
  public Map<Long,String> ruins=new LinkedHashMap<>();public Map<Long,UUID> ruinOwners=new HashMap<>();
  @com.google.gson.annotations.JsonAdapter(CityBlockStore.Adapter.class) public Map<Long,String> terrain=new CityBlockStore();public Map<Long,String> illegal=new LinkedHashMap<>();
  public Set<Long> capturedChunks=new HashSet<>();public boolean deferredTerrain;public List<long[]> unknownTerrain=new ArrayList<>();
  public Map<Long,List<String>> drops=new LinkedHashMap<>();public Set<Long> deferredContainers=new HashSet<>();
  public Map<Long,Projection> pending=new LinkedHashMap<>();
  public Map<String,Integer> resources=new TreeMap<>();public Map<String,Long> materialsConsumed=new TreeMap<>(),recovered=new TreeMap<>(),crafted=new TreeMap<>();
  public Map<UUID,Long> arrivals=new LinkedHashMap<>();
  public Map<UUID,Long> emergencyCredit=new LinkedHashMap<>();
  public Map<UUID,Long> quotaCredit=new LinkedHashMap<>();
  public List<Segment> queue=new ArrayList<>();
 }
 public static final class Projection {public String target,expected,reason;public Projection(){}Projection(String t,String e,String r){target=t;expected=e;reason=r;}}
 public static final class Segment {public long day;public List<UUID> workers=new ArrayList<>();public int cursor;public Segment(){}Segment(long d,List<UUID> w){day=d;workers=w;}}
 private record Capture(UUID city,long revision,CityScanCursor cursor,Map<Long,String> terrain,boolean append){}
 private record Task(long pos,BlockState target,CityHousing.House house,int rank,String kind){}
 private static final Map<UUID,Capture> captures=new LinkedHashMap<>();private static int cityCursor;
 private static final Map<CityData.City,CityScanCursor> localScans=new WeakHashMap<>();
 static List<long[]> pendingSnapshot(CityData.City c){return List.copyOf(c.works.unknownTerrain);}
 static void validateResize(CityData.City c,CityBounds next){
  CityEconomy.require(c.works.pending.keySet().stream().allMatch(p->next.contains(BlockPos.of(p)))&&c.works.ruins.keySet().stream().allMatch(p->next.contains(BlockPos.of(p)))&&c.works.deferredContainers.stream().allMatch(p->next.contains(BlockPos.of(p))),"缩小范围会移除待施工、待结算容器或有产权的残骸；请先完成这些任务。");
 }
 static void trimForResize(CityData.City c,CityBounds next){
  var kept=new ArrayList<long[]>();for(var area:unknown(c)){var clip=CityAreas.intersection(area,next);if(clip!=null)kept.add(new long[]{clip.min().asLong(),clip.max().asLong()});}c.works.unknownTerrain=kept;c.works.deferredTerrain=!kept.isEmpty();
  if(c.works.terrain instanceof CityBlockStore store)store.retainWithin(next);else c.works.terrain.keySet().removeIf(p->!next.contains(BlockPos.of(p)));
  c.works.illegal.keySet().removeIf(p->!next.contains(BlockPos.of(p)));c.works.terrainDamage.removeIf(p->!next.contains(BlockPos.of(p)));c.works.damageSince.keySet().removeIf(p->!next.contains(BlockPos.of(p)));localScans.remove(c);taskCache.remove(c);
 }
 private record UnknownCache(Object source,List<CityBounds> boxes,CityAreas.Index index){}
 private static final Map<Plan,UnknownCache> unknownCache=new WeakHashMap<>();
 static List<CityBounds> unknown(CityData.City c){var cached=unknownCache.get(c.works);if(cached!=null&&cached.source==c.works.unknownTerrain)return cached.boxes;var out=new ArrayList<CityBounds>();for(var row:c.works.unknownTerrain){if(row==null||row.length!=2)throw new IllegalArgumentException("待记录地形区域无效");out.add(new CityBounds(BlockPos.of(row[0]),BlockPos.of(row[1])));}var boxes=List.copyOf(out);unknownCache.put(c.works,new UnknownCache(c.works.unknownTerrain,boxes,new CityAreas.Index(boxes)));return boxes;}
 private static void editUnknown(CityData.City c,CityBounds area,boolean include){var out=new ArrayList<CityBounds>();for(var b:unknown(c))CityAreas.subtract(b,area,out);if(include)out.add(area);var rows=new ArrayList<long[]>();for(var b:out)rows.add(new long[]{b.min().asLong(),b.max().asLong()});c.works.unknownTerrain=rows;c.works.deferredTerrain=!rows.isEmpty();}
 static void areaChanged(CityData.City c,CityBounds changed,boolean include){
  localScans.remove(c);if(!c.works.finalized)return;
  if(!include){editUnknown(c,changed,false);return;}
  var missing=new ArrayList<CityBounds>();missing.add(changed);
  for(var old:CityAreas.regions(c)){var next=new ArrayList<CityBounds>();for(var box:missing)CityAreas.subtract(box,old,next);missing=next;}
  for(var box:missing)editUnknown(c,box,true);
  for(long key:c.excluded){var pos=BlockPos.of(key);if(changed.contains(pos)&&CityAreas.regions(c).stream().anyMatch(v->v.contains(pos)))editUnknown(c,new CityBounds(pos,pos),true);}
 }
 static boolean recorded(CityData.City c,BlockPos pos){if(!c.works.deferredTerrain)return true;unknown(c);return !unknownCache.get(c.works).index.contains(pos);}
 static void beforeTerrainEdit(ServerLevel l,BlockPos pos,BlockState before){
  var c=RuralTools.city(l,pos);if(c!=null&&c.works.finalized&&!recorded(c,pos)){c.works.terrain.putIfAbsent(pos.asLong(),CityMaintenance.encode(before));CityData.get(l.getServer()).setDirty();}
 }
 private static void appendLoadedTerrain(MinecraftServer s){
  if(s.getTickCount()%20!=0)return;
  for(var c:CityData.get(s).cities())if(c.works.finalized&&c.works.deferredTerrain){var l=CityEconomy.level(s,c);for(var box:CityLoadedChunks.boxes(l,c.bounds))for(var missing:unknown(c)){var part=CityAreas.intersection(box,missing);if(part!=null){captures.put(c.id,new Capture(c.id,c.revision,new CityScanCursor(List.of(part)),new CityBlockStore(),true));return;}}}
 }
 private static boolean houseChunksRecorded(CityData.City c,CityBounds b){
  if(!c.works.deferredTerrain)return true;for(var area:unknown(c))if(area.intersects(b))return false;return true;
 }
 private static void completeHouseBaselines(CityData.City c){
  for(var b:c.buildings.values()){var h=CityHousing.house(c,b.id());if(!h.baseline.isEmpty()||!houseChunksRecorded(c,b.bounds()))continue;
   for(int i=0;i<b.bounds().volume();i++){var pos=b.bounds().at(i);String target=c.works.terrain.get(pos.asLong());if(target!=null&&!CityBlockRules.ignored(state(target)))h.baseline.put(pos.asLong(),target);}
   h.extra=false;h.stage="BUILT";h.damaged.clear();
  }
 }
 private record TaskCache(long clock,List<Task> tasks){}private record EffCache(long clock,Map<UUID,Integer> values){}
 private static final Map<CityData.City,TaskCache> taskCache=new WeakHashMap<>();private static final Map<CityData.City,EffCache> efficiencyCache=new WeakHashMap<>();private static final Map<String,BlockState> decoded=new LinkedHashMap<>();
 static BlockState state(String value){var result=decoded.get(value);if(result==null){if(decoded.size()>=4096)decoded.clear();result=CityMaintenance.decode(value);decoded.put(value,result);}return result;}
 static void clear(){captures.clear();localScans.clear();unknownCache.clear();taskCache.clear();efficiencyCache.clear();decoded.clear();cityCursor=0;}
 static boolean active(CityData.City c){return c.works.finalized&&c.works.enabled;}
 static boolean workshop(CityData.City c,UUID id){var b=c.buildings.get(id);return b!=null&&b.type().equals("工坊");}
 static boolean living(MinecraftServer s,CityData.City c,UUID id){if(!c.residents.contains(id))return false;var person=RuralSettlement.get(s).state.people.get(id);if(person!=null)return !person.dead;return CityMaintenance.available(CityEconomy.level(s,c),c,id);}
 static Set<UUID> staff(MinecraftServer s,CityData.City c,UUID id){var out=new LinkedHashSet<UUID>();var h=c.housing.houses.get(id);if(h!=null)out.addAll(h.workers);for(var j:CityEconomy.get(s).state.production)if(j.enabled&&j.city.equals(c.id)&&j.building.equals(id))out.add(j.worker);var b=c.buildings.get(id);if(b!=null)for(var site:RuralSettlement.get(s).state.sites.values())if(site.city.equals(c.id)&&site.worker!=null&&b.bounds().contains(BlockPos.of(site.pos)))out.add(site.worker);out.removeIf(npc->!living(s,c,npc));return out;}
 static long health(CityHousing.House h){return h.baseline.size()-h.damaged.size();}
 static int efficiency(CityHousing.House h){if(h==null||!h.configured)return 10000;if(!h.stage.equals("BUILT")||h.baseline.isEmpty())return 0;return (int)(10000*health(h)/h.baseline.size());}
 static int workerEfficiency(MinecraftServer s,CityData.City c,UUID npc){if(c.housing.houses.isEmpty())return 10000;var cache=efficiencyCache.get(c);long clock=c.works.finalized?c.works.clock:s.overworld().getGameTime()/20;if(cache==null||cache.clock!=clock){var values=new HashMap<UUID,Integer>();for(var entry:c.housing.houses.entrySet())for(UUID id:staff(s,c,entry.getKey()))values.put(id,efficiency(entry.getValue()));cache=new EffCache(clock,values);efficiencyCache.put(c,cache);}return cache.values.getOrDefault(npc,10000);}
 static void beginFinalize(MinecraftServer s,CityData.City c){CityEconomy.require(!c.works.finalized,"首次定稿已经完成；追加建筑请下达蓝图");CityEconomy.require(!captures.containsKey(c.id),"正在记录，请等待");var l=CityEconomy.level(s,c);if(c.bounds.smallSelection())for(int x=c.bounds.min().getX()>>4;x<=c.bounds.max().getX()>>4;x++)for(int z=c.bounds.min().getZ()>>4;z<=c.bounds.max().getZ()>>4;z++)CityEconomy.require(l.hasChunk(x,z),"首次定稿请先靠近范围；不强制加载区块");captures.put(c.id,new Capture(c.id,c.revision,new CityScanCursor(CityLoadedChunks.scanBoxes(l,c.bounds)),new CityBlockStore(),false));c.works.status="分批记录首次定稿地形";CityData.get(s).setDirty();}
 static void capture(MinecraftServer s){if(captures.isEmpty()){appendLoadedTerrain(s);if(captures.isEmpty())return;}var task=captures.values().iterator().next();var c=CityData.get(s).cities.get(task.city);if(c==null||c.revision!=task.revision){captures.remove(task.city);return;}var l=CityEconomy.level(s,c);task.cursor.step(l,1024,pos->{if(c.includes(pos)&&!l.getBlockState(pos).isAir())task.terrain.put(pos.asLong(),CityMaintenance.encode(l.getBlockState(pos)));},air->{});if(task.cursor.lostChunk){captures.remove(c.id);c.works.status="记录区块已卸载；保持已有基准，靠近后继续";return;}
  if(!task.cursor.done())return;if(task.terrain instanceof CityBlockStore store)store.compact();
  if(task.append){for(var entry:task.terrain.entrySet())c.works.terrain.putIfAbsent(entry.getKey(),entry.getValue());for(var box:task.cursor.boxes){c.works.capturedChunks.add(net.minecraft.world.level.ChunkPos.asLong(box.min().getX()>>4,box.min().getZ()>>4));editUnknown(c,box,false);}if(c.works.terrain instanceof CityBlockStore store)store.compact();completeHouseBaselines(c);c.works.status="已记录地形区块："+c.works.capturedChunks.size()+"；远方未加载地区保留待记录状态";captures.remove(c.id);CityData.get(s).setDirty();return;}
  c.works.terrain=task.terrain;var legacy=CityMaintenance.get(s);var legacyPlan=legacy.state.cities.computeIfAbsent(c.id,k->new CityMaintenance.Plan());legacyPlan.baseline=new CityBlockStore(task.terrain);legacyPlan.collective=false;legacy.setDirty();
  for(var box:task.cursor.boxes)for(int x=box.min().getX()>>4;x<=box.max().getX()>>4;x++)for(int z=box.min().getZ()>>4;z<=box.max().getZ()>>4;z++)c.works.capturedChunks.add(net.minecraft.world.level.ChunkPos.asLong(x,z));c.works.unknownTerrain=new ArrayList<>();if(!c.bounds.smallSelection()){for(var box:CityAreas.regions(c))editUnknown(c,box,true);for(var box:task.cursor.boxes)editUnknown(c,box,false);}
  completeHouseBaselines(c);c.works.day=RuralSettlement.dayTime(s,c);c.works.finalized=true;c.works.nextSegment=3000-Math.floorMod(c.works.day,3000);c.works.status=c.works.deferredTerrain?"已定稿当前加载地区；远方地形待加载后记录":"首次定稿完成，城市维护已启动";captures.remove(c.id);CityMaintenance.enableDataCity(s,c);CityData.get(s).setDirty();
 }
 static CityHousing.House at(CityData.City c,long pos){var p=BlockPos.of(pos);for(var b:c.buildings.values())if(b.bounds().contains(p))return c.housing.houses.get(b.id());return null;}
 static String target(CityData.City c,long pos){var h=at(c,pos);if(h!=null&&h.baseline.containsKey(pos)&&!h.stage.equals("ABANDONED"))return h.baseline.get(pos);if(h!=null&&h.clears.contains(pos)&&!h.stage.equals("ABANDONED"))return CityMaintenance.encode(Blocks.AIR.defaultBlockState());return c.works.terrain.getOrDefault(pos,CityMaintenance.encode(Blocks.AIR.defaultBlockState()));}
 static boolean artisanWorkshop(MinecraftServer s,CityData.City c,UUID id){var h=c.housing.houses.get(id);return workshop(c,id)&&h!=null&&(h.artisanWorkshop||staff(s,c,id).stream().anyMatch(npc->{var w=CityMaintenance.get(s).state.workers.get(npc);return w!=null&&w.enabled&&w.artisan;}));}
 static boolean emergency(MinecraftServer s,CityData.City c){boolean any=false;for(var e:c.housing.houses.entrySet())if(artisanWorkshop(s,c,e.getKey())&&e.getValue().stage.equals("BUILT")){any=true;if(health(e.getValue())>0)return false;}return any;}
 /** Emergency recovery ends only when every existing damaged workshop has recovered. */
 static void updateEmergency(MinecraftServer s,CityData.City c){c.works.emergency=c.works.emergency?c.housing.houses.entrySet().stream().anyMatch(e->workshop(c,e.getKey())&&e.getValue().stage.equals("BUILT")&&!e.getValue().damaged.isEmpty()):emergency(s,c);}
 static void observe(MinecraftServer s,CityData.City c,long pos,BlockState actual){if(!active(c)||!c.includes(BlockPos.of(pos))||c.works.pending.containsKey(pos))return;var h=at(c,pos);if(h!=null&&h.baseline.containsKey(pos)){
   if(h.stage.equals("ABANDONED"))return;var wanted=state(h.baseline.get(pos));if(CityBlockRules.same(actual,wanted)){h.damaged.remove(pos);c.works.damageSince.remove(pos);}else{h.damaged.add(pos);c.works.damageSince.putIfAbsent(pos,c.works.clock);}if(h.stage.equals("PLANNED"))return;
  }var wanted=state(target(c,pos));if(CityBlockRules.ignored(actual)||CityBlockRules.ignored(wanted)){c.works.illegal.remove(pos);c.works.terrainDamage.remove(pos);return;}if(h!=null&&h.pendingClear.contains(pos)&&actual.isAir()){h.pendingClear.remove(pos);completed(h);}if(CityBlockRules.same(actual,wanted)||actual.isAir())c.works.illegal.remove(pos);else c.works.illegal.put(pos,CityMaintenance.encode(actual));
 }
 static void changed(ServerLevel l,BlockPos p,boolean removed){var c=RuralTools.city(l,p);if(c==null||!active(c)||(!recorded(c,p)&&!c.works.terrain.containsKey(p.asLong())&&at(c,p.asLong())==null))return;c.works.pending.remove(p.asLong());taskCache.remove(c);efficiencyCache.remove(c);var actual=removed?Blocks.AIR.defaultBlockState():l.getBlockState(p);observe(l.getServer(),c,p.asLong(),actual);CityData.get(l.getServer()).setDirty();}
 static void schedule(CityData.City c,long pos,BlockState wanted,BlockState actual,String reason){String expected=c.works.pending.containsKey(pos)?c.works.pending.get(pos).expected:CityMaintenance.encode(actual);c.works.pending.put(pos,new Projection(CityMaintenance.encode(wanted),expected,reason));}
 static void decay(MinecraftServer s,CityData.City c){int population=0;var rural=RuralSettlement.get(s);for(UUID id:c.residents){var p=rural.state.people.get(id);if(p!=null){if(!p.dead&&p.age!=RuralRules.Age.INFANT)population++;}else if(living(s,c,id))population++;}int rate=Math.min(10000,400+Math.max(0,(population-80)/10)*50);var random=s.overworld().random;
  for(var e:c.housing.houses.entrySet()){var h=e.getValue();if(h.baseline.isEmpty()||(workshop(c,e.getKey())&&!staff(s,c,e.getKey()).isEmpty()))continue;var regular=new ArrayList<Long>();var protectedBlocks=new ArrayList<Long>();for(var b:h.baseline.entrySet())if(!h.damaged.contains(b.getKey())){var state=state(b.getValue());if(CityBlockRules.decays(state))(CityBlockRules.last(state)?protectedBlocks:regular).add(b.getKey());}h.decayCredit+=(long)(regular.size()+protectedBlocks.size())*rate;long amount=h.decayCredit/10000;h.decayCredit%=10000;for(long n=0;n<amount;n++){var options=regular.isEmpty()?protectedBlocks:regular;if(options.isEmpty())break;int index=random.nextInt(options.size());long p=options.remove(index);h.damaged.add(p);c.works.damageSince.putIfAbsent(p,c.works.clock);destroyInventory(s,c,p);schedule(c,p,Blocks.AIR.defaultBlockState(),state(h.baseline.get(p)),"NATURAL");}}
 }
 static void addTask(List<Task> tasks,int[] buckets,Task task){if(buckets[task.rank]++<512)tasks.add(task);}
 static List<Task> tasks(CityData.City c){var cached=taskCache.get(c);if(cached!=null&&cached.clock==c.works.clock)return cached.tasks;int[] buckets=new int[6];var list=new ArrayList<Task>();for(var e:c.housing.houses.entrySet()){var h=e.getValue();if(h.stage.equals("ABANDONED")){for(var b:h.baseline.entrySet())if(!h.damaged.contains(b.getKey()))addTask(list,buckets,new Task(b.getKey(),Blocks.AIR.defaultBlockState(),h,5,"ABANDONED"));continue;}int rank=h.stage.equals("PLANNED")?4:workshop(c,e.getKey())?0:2;for(long p:h.damaged){var wanted=state(h.baseline.get(p));addTask(list,buckets,new Task(p,wanted,h,rank==2&&CityBlockRules.workstation(wanted)?1:rank,h.stage.equals("PLANNED")?"BUILD":"REPAIR"));}}
  for(var e:c.works.terrain.entrySet()){if(at(c,e.getKey())!=null)continue;if(c.works.terrainDamage.contains(e.getKey()))addTask(list,buckets,new Task(e.getKey(),state(e.getValue()),null,2,"TERRAIN"));}
  for(var e:c.works.ruins.entrySet()){var h=new CityHousing.House();h.personal=c.works.ruinOwners.containsKey(e.getKey());h.owner=c.works.ruinOwners.get(e.getKey());addTask(list,buckets,new Task(e.getKey(),Blocks.AIR.defaultBlockState(),h,5,"RUIN"));}
  for(var e:c.works.illegal.entrySet())addTask(list,buckets,new Task(e.getKey(),Blocks.AIR.defaultBlockState(),at(c,e.getKey()),3,"ILLEGAL"));list.sort(Comparator.comparingInt(Task::rank).thenComparingDouble(t->t.house==null?1:(double)health(t.house)/Math.max(1,t.house.baseline.size())).thenComparingLong(t->c.works.damageSince.getOrDefault(t.pos,c.works.clock)).thenComparingLong(Task::pos));taskCache.put(c,new TaskCache(c.works.clock,list));return list;
 }
 static void reclaim(CityData.City c,CityHousing.House h,BlockState old){String item=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(old.getBlock().asItem()).toString();if(item.equals("minecraft:air"))return;if(h!=null&&h.personal){if(h.materials.getOrDefault(item,0)<4096)h.materials.merge(item,1,Integer::sum);else c.works.resources.merge(item,1,Integer::sum);}else{var market=c.housing.market.computeIfAbsent(item,k->new CityHousing.Material());if(market.stock<4096)market.stock++;else c.works.resources.merge(item,1,Integer::sum);}c.works.recovered.merge(item,1L,Long::sum);}
 static BlockState dataAt(MinecraftServer s,CityData.City c,long p){if(c.works.pending.containsKey(p))return state(c.works.pending.get(p).target);var l=CityEconomy.level(s,c);if(!c.works.virtual&&l.hasChunkAt(BlockPos.of(p)))return l.getBlockState(BlockPos.of(p));var h=at(c,p);if(h!=null&&h.baseline.containsKey(p))return state(!h.damaged.contains(p)?h.baseline.get(p):c.works.illegal.getOrDefault(p,CityMaintenance.encode(Blocks.AIR.defaultBlockState())));if(c.works.ruins.containsKey(p))return state(c.works.ruins.get(p));if(c.works.illegal.containsKey(p))return state(c.works.illegal.get(p));return state(c.works.terrainDamage.contains(p)?CityMaintenance.encode(Blocks.AIR.defaultBlockState()):c.works.terrain.getOrDefault(p,CityMaintenance.encode(Blocks.AIR.defaultBlockState())));}
 static BlockState actualData(MinecraftServer s,CityData.City c,Task task){long p=task.pos;if(c.works.pending.containsKey(p))return state(c.works.pending.get(p).target);var l=CityEconomy.level(s,c);if(!c.works.virtual&&l.hasChunkAt(BlockPos.of(p)))return l.getBlockState(BlockPos.of(p));if(task.kind.equals("RUIN"))return state(c.works.ruins.getOrDefault(p,CityMaintenance.encode(Blocks.AIR.defaultBlockState())));if(task.house!=null&&task.house.baseline.containsKey(p)&&!task.house.damaged.contains(p))return state(task.house.baseline.get(p));return state(c.works.illegal.getOrDefault(p,CityMaintenance.encode(Blocks.AIR.defaultBlockState())));}
 static boolean needed(CityData.City c,Task task){return switch(task.kind){case "REPAIR","BUILD"->task.house!=null&&!task.house.stage.equals("ABANDONED")&&task.house.damaged.contains(task.pos);case "ABANDONED"->task.house!=null&&task.house.stage.equals("ABANDONED")&&!task.house.damaged.contains(task.pos);case "RUIN"->c.works.ruins.containsKey(task.pos);case "ILLEGAL"->c.works.illegal.containsKey(task.pos);case "TERRAIN"->c.works.terrainDamage.contains(task.pos);default->false;};}
 static void completed(CityHousing.House h){if(h!=null&&h.stage.equals("PLANNED")&&h.damaged.isEmpty()&&h.pendingClear.isEmpty()){h.stage="BUILT";h.status="建筑已竣工";}}
 static boolean runnable(MinecraftServer s,CityData.City c,Task task,UUID owner,String payer,int normalQuota){if(!needed(c,task))return false;if(task.rank>0&&normalQuota==0)return false;if(owner!=null&&(task.house==null||!task.house.personal||!owner.equals(task.house.owner)))return false;var actual=actualData(s,c,task);if(CityBlockRules.same(actual,task.target))return false;if(!actual.isAir())return true;return CityWorksFinance.canMaterial(s,c,task.house,task.target,c.works.emergency&&task.rank==0,payer);}
 static int perform(MinecraftServer s,CityData.City c,UUID owner,int quota){return perform(s,c,owner,quota,quota);}
 static int perform(MinecraftServer s,CityData.City c,UUID owner,int quota,int normalLimit){int done=0;var l=CityEconomy.level(s,c);for(var task:tasks(c)){if(done>=quota)break;if(!needed(c,task))continue;if(task.rank>0&&done>=normalLimit)continue;if(owner!=null&&(task.house==null||!task.house.personal||!owner.equals(task.house.owner)))continue;long p=task.pos;BlockState old=actualData(s,c,task);
   boolean removing=task.target.isAir()||(!old.isAir()&&!CityBlockRules.same(old,task.target));if(!removing&&CityBlockRules.same(old,task.target)){if(task.house!=null)task.house.damaged.remove(p);if(task.house!=null){task.house.pendingClear.remove(p);completed(task.house);}c.works.damageSince.remove(p);c.works.terrainDamage.remove(p);continue;}
   if(removing){if(old.isAir()){c.works.illegal.remove(p);if(task.kind.equals("RUIN")){c.works.ruins.remove(p);c.works.ruinOwners.remove(p);}if(task.house!=null&&task.kind.equals("ABANDONED"))task.house.damaged.add(p);continue;}destroyInventory(s,c,p);reclaim(c,task.house,old);schedule(c,p,Blocks.AIR.defaultBlockState(),old,task.kind);c.works.illegal.remove(p);if(task.kind.equals("RUIN")){c.works.ruins.remove(p);c.works.ruinOwners.remove(p);}c.works.ruins.remove(p);c.works.ruinOwners.remove(p);if(task.house!=null){if(task.house.baseline.containsKey(p))task.house.damaged.add(p);task.house.pendingClear.remove(p);completed(task.house);}c.works.demolished++;done++;continue;}
   if(task.house!=null&&task.house.personal&&task.house.owner==null)continue;boolean aid=c.works.emergency&&task.house!=null&&task.rank==0;if(!CityWorksFinance.material(s,c,task.house,task.target,aid))continue;schedule(c,p,task.target,old,task.kind);if(task.house!=null){task.house.damaged.remove(p);completed(task.house);}c.works.terrainDamage.remove(p);c.works.damageSince.remove(p);if(task.kind.equals("BUILD"))c.works.constructed++;else c.works.repaired++;done++;
  }return done;
 }
 static void worker(MinecraftServer s,CityData.City c,UUID npc,long day){var d=RuralSettlement.get(s);var person=d.state.people.get(npc);if(!living(s,c,npc)||person!=null&&(person.dead||person.role==RuralRules.Role.VAGRANT))return;var worker=CityMaintenance.get(s).state.workers.get(npc);if(worker==null||!worker.enabled||!worker.artisan)return;var cfg=WorkHours.config(s,npc);if(!WorkHours.allowed(cfg,day,CityLiving.stability(CityEconomy.get(s),c),Math.floorMod(Objects.hash(npc,Math.floorDiv(day-12000,24000)),100)))return;
  boolean foundation=c.works.virtual&&c.housing.houses.entrySet().stream().anyMatch(e->workshop(c,e.getKey())&&e.getValue().stage.equals("PLANNED")&&e.getValue().workers.contains(npc));int factor=c.works.emergency||foundation?10000:workerEfficiency(s,c,npc);if(person!=null)factor=(int)Math.round(factor*FamilyLivelihood.workFactor(s,person));if(person!=null)factor=(int)Math.round(factor*RuralRules.efficiency(person.trainedHours));long credit=c.works.quotaCredit.getOrDefault(npc,0L)+(long)10*factor*worker.perHour/30;int quota=(int)Math.min(10,credit/10000);c.works.quotaCredit.put(npc,credit%10000);int normalQuota=quota;long rescue=c.works.emergencyCredit.getOrDefault(npc,0L)+(long)Math.round(100000*(person==null?1:RuralRules.efficiency(person.trainedHours))*worker.perHour/30.0);int rescueQuota=(int)Math.min(10,rescue/10000);c.works.emergencyCredit.put(npc,rescue%10000);var available=tasks(c);if(available.stream().anyMatch(task->task.rank==0))quota=Math.max(quota,rescueQuota);String pub=CityWorksFinance.publicPayer(s,c),payer=null;UUID owner=null;int activeWage=CityWorksFinance.wage(s,c,true),standbyWage=CityWorksFinance.wage(s,c,false);int reserved=activeWage;int normalForCheck=normalQuota;
  if(quota>0&&available.stream().anyMatch(t->runnable(s,c,t,null,pub,normalForCheck))&&CityWorksFinance.reserve(s,c,npc,pub,activeWage))payer=pub;
  if(payer==null&&quota>0){var owners=available.stream().map(Task::house).filter(Objects::nonNull).filter(h->h.personal&&h.owner!=null).map(h->h.owner).distinct().toList();for(int i=0;i<owners.size();i++){UUID candidate=owners.get(Math.floorMod(c.works.privateCursor+i,owners.size()));String account=CityEconomy.person(candidate);if(available.stream().anyMatch(t->runnable(s,c,t,candidate,account,normalForCheck))&&CityWorksFinance.reserve(s,c,npc,account,activeWage)){owner=candidate;payer=account;c.works.privateCursor=(c.works.privateCursor+i+1)%owners.size();break;}}}
  if(payer==null&&CityWorksFinance.reserve(s,c,npc,pub,standbyWage)){payer=pub;reserved=standbyWage;quota=0;}
  if(payer==null){c.works.status="付款方不足，工作段暂停";return;}if(person!=null&&!RuralSettlement.active(s,c.id)){person.trainingTicks+=3000;while(person.trainingTicks>=72000){person.trainingTicks-=72000;person.trainedHours=Math.min(9,person.trainedHours+1);}}int done=0;long before=c.works.repaired+c.works.constructed+c.works.demolished;try{if(reserved==activeWage)perform(s,c,owner,quota,normalQuota);}catch(IllegalArgumentException ex){c.works.status="维护暂停检查："+ex.getMessage();c.works.enabled=false;}finally{done=(int)(c.works.repaired+c.works.constructed+c.works.demolished-before);CityWorksFinance.settle(s,c,npc,payer,reserved,done);}c.works.status="工匠本段完成"+done+"块；工资"+(done>0?activeWage:standbyWage)+"银币";
 }
 static void destroyInventory(MinecraftServer s,CityData.City c,long packed){var l=CityEconomy.level(s,c);var pos=BlockPos.of(packed);var rural=RuralSettlement.get(s);var box=rural.state.boxes.get(RuralSettlement.key(c.id,packed));var loot=new ArrayList<net.minecraft.world.item.ItemStack>();if(box!=null){loot.addAll(NpcStorage.projected(l,box));NpcStorage.counts(box.stock,new int[12]);box.slots.clear();box.present=false;if(l.hasChunkAt(pos)&&l.getBlockEntity(pos) instanceof RuralBlocks.Link link){link.inventory=null;NpcStorage.live.remove(link);}rural.setDirty();}else {var warehouse=c.warehouses.values().stream().filter(w->w.pos().equals(pos)).findFirst().orElse(null);net.minecraft.world.Container container=null;if(warehouse!=null)try{container=CityEconomy.warehouse(l,c,warehouse.id());}catch(IllegalArgumentException ignored){}if(container==null&&l.hasChunkAt(pos)&&l.getBlockEntity(pos) instanceof net.minecraft.world.Container physical)container=physical;if(container!=null){for(int i=0;i<container.getContainerSize();i++){var stack=container.removeItemNoUpdate(i);if(!stack.isEmpty())loot.add(stack);}container.setChanged();CitySimulation.afterCommit(container);}if(!l.hasChunkAt(pos)&&CityBlockRules.last(state(target(c,packed))))c.works.deferredContainers.add(packed);}if(!loot.isEmpty()){var stored=c.works.drops.computeIfAbsent(packed,k->new ArrayList<>());for(var stack:loot)if(!stack.isEmpty())stored.add(stack.save(l.registryAccess()).toString());}}
 static void project(MinecraftServer s,CityData.City c){if(c.works.virtual)return;var l=CityEconomy.level(s,c);int count=0;
  for(long packed:new ArrayList<>(c.works.deferredContainers)){var pos=BlockPos.of(packed);if(!l.hasChunkAt(pos))continue;c.works.deferredContainers.remove(packed);destroyInventory(s,c,packed);if(++count>=4)break;}
  for(var entry:new ArrayList<>(c.works.drops.entrySet())){var pos=BlockPos.of(entry.getKey());if(!l.hasChunkAt(pos))continue;var items=entry.getValue();while(!items.isEmpty()&&count<8){String encoded=items.removeFirst();try{var stack=net.minecraft.world.item.ItemStack.parseOptional(l.registryAccess(),net.minecraft.nbt.TagParser.parseTag(encoded));Block.popResource(l,pos,stack);count++;}catch(Exception ex){items.addFirst(encoded);throw new IllegalArgumentException("待掉落物品记录无效，记录已保留",ex);}}if(items.isEmpty())c.works.drops.remove(entry.getKey());if(count>=8)break;}
  count=0;for(var entry:new ArrayList<>(c.works.pending.entrySet())){var pos=BlockPos.of(entry.getKey());if(!l.hasChunkAt(pos))continue;var target=state(entry.getValue().target);var actual=l.getBlockState(pos);if(CityBlockRules.same(actual,target)){c.works.pending.remove(entry.getKey());continue;}if(!target.getCollisionShape(l,pos).isEmpty()&&!l.getEntities(null,new net.minecraft.world.phys.AABB(pos)).isEmpty())continue;
   if(!CityBlockRules.same(actual,state(entry.getValue().expected))){c.works.pending.remove(entry.getKey());observe(s,c,entry.getKey(),actual);continue;}
   if(l.getBlockEntity(pos) instanceof net.minecraft.world.Container container&&!(container instanceof RuralBlocks.Link))net.minecraft.world.Containers.dropContents(l,pos,container);l.setBlock(pos,target,2);var house=at(c,entry.getKey());if(house!=null&&house.blockData.containsKey(entry.getKey())&&l.getBlockEntity(pos)!=null)try{l.getBlockEntity(pos).loadWithComponents(net.minecraft.nbt.TagParser.parseTag(house.blockData.get(entry.getKey())),l.registryAccess());l.getBlockEntity(pos).setChanged();}catch(Exception ex){c.works.status="方块外观/关联配置同步失败："+ex.getMessage();}c.works.pending.remove(entry.getKey());if(++count>=8)break;}
 }
 static void tick(MinecraftServer s){capture(s);var cities=CityData.get(s).cities().stream().filter(CityWorks::active).toList();if(cities.isEmpty())return;var c=cities.get(Math.floorMod(cityCursor++,cities.size()));var l=CityEconomy.level(s,c);if(!c.works.virtual){var scan=localScans.get(c);if(scan==null||scan.done()){scan=new CityScanCursor(CityLoadedChunks.scanBoxes(l,c.bounds));localScans.put(c,scan);}scan.step(l,256,pos->{if(c.includes(pos)&&recorded(c,pos)){observe(s,c,pos.asLong(),l.getBlockState(pos));if(at(c,pos.asLong())==null&&c.works.terrain.containsKey(pos.asLong())&&!CityBlockRules.ignored(l.getBlockState(pos))&&!CityBlockRules.same(l.getBlockState(pos),state(c.works.terrain.get(pos.asLong())))){c.works.terrainDamage.add(pos.asLong());c.works.damageSince.putIfAbsent(pos.asLong(),c.works.clock);}else if(at(c,pos.asLong())==null)c.works.terrainDamage.remove(pos.asLong());}},air->{});}
  project(s,c);int steps=SimulationClock.steps(s);if(steps>0){for(var city:cities){var p=city.works;p.clock+=20L*steps;p.day+=20L*steps;if(s.getTickCount()%20==0||p.clock>=p.nextSegment)updateEmergency(s,city);if(p.emergency&&!p.emergencyAnnounced){RuralSuccession.emergencyNow(s,city);p.emergencyAnnounced=true;}if(!p.emergency)p.emergencyAnnounced=false;if(p.clock>=p.nextDecay){p.nextDecay+=72000;decay(s,city);}if(p.clock>=p.nextSegment){p.nextSegment+=3000;var artisans=CityMaintenance.get(s).state.workers.entrySet().stream().filter(e->e.getValue().enabled&&e.getValue().artisan&&e.getValue().city.equals(city.id)).map(Map.Entry::getKey).sorted().toList();if(p.queue.size()<64)p.queue.add(new Segment(p.day-3000,artisans));}if(p.clock>=p.nextMeal){p.nextMeal+=36000;RuralSuccession.artisanMeals(s,city);}if(s.getTickCount()%20==0||p.clock%1200<20L*steps)RuralSuccession.tick(s,city);}}
  if(!c.works.queue.isEmpty()){var q=c.works.queue.getFirst();int processed=0;while(q.cursor<q.workers.size()&&processed++<2)worker(s,c,q.workers.get(q.cursor++),q.day);if(q.cursor==q.workers.size())c.works.queue.removeFirst();}CityData.get(s).setDirty();
 }
 static void validate(Plan p,CityData.City c){CityEconomy.require(p!=null&&p.terrain!=null&&p.unknownTerrain!=null&&p.queue.size()<=64&&p.resources.size()<=256,"城市维护数据超限");for(var row:p.unknownTerrain){CityEconomy.require(row!=null&&row.length==2,"待记录地形无效");var area=new CityBounds(BlockPos.of(row[0]),BlockPos.of(row[1]));CityEconomy.require(c.bounds.contains(area.min())&&c.bounds.contains(area.max()),"待记录地形越界");}p.deferredTerrain=!p.unknownTerrain.isEmpty();CityEconomy.require(CityBlockStore.inside(p.terrain,c.bounds),"维护地形越界");for(String value:CityBlockStore.states(p.terrain))state(value);for(var v:p.resources.values())CityEconomy.require(v>=0&&v<=1000000,"公共资源库存越界");}
}
